import React, { useState } from 'react';
import Icon from 'components/AppIcon';
import { useFlashcards } from '../../../contexts/FlashcardContext';

const CreateFlashcardModal = ({ onClose }) => {
  const { createCard } = useFlashcards();
  const [front, setFront] = useState('');
  const [back, setBack] = useState('');
  const [saving, setSaving] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!front.trim() || !back.trim()) return;
    setSaving(true);
    try {
      await createCard({ front: front.trim(), back: back.trim(), tags: ['custom'] });
      onClose();
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
      <div className="bg-surface border border-border rounded-lg shadow-warm-lg w-full max-w-md p-6">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-lg font-heading font-semibold">New Flashcard</h2>
          <button onClick={onClose} aria-label="Close">
            <Icon name="X" size={20} />
          </button>
        </div>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium mb-1">Front (question)</label>
            <textarea
              value={front}
              onChange={(e) => setFront(e.target.value)}
              className="input w-full min-h-[80px]"
              required
            />
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">Back (answer)</label>
            <textarea
              value={back}
              onChange={(e) => setBack(e.target.value)}
              className="input w-full min-h-[80px]"
              required
            />
          </div>
          <div className="flex gap-2 justify-end">
            <button type="button" onClick={onClose} className="btn btn-outline px-4 py-2">
              Cancel
            </button>
            <button type="submit" disabled={saving} className="btn btn-primary px-4 py-2">
              {saving ? 'Saving...' : 'Create'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default CreateFlashcardModal;
