import React, { useState } from 'react';
import Icon from 'components/AppIcon';
import { useFlashcards } from '../../../contexts/FlashcardContext';

const QUALITY_LABELS = [
  { q: 0, label: 'Blackout', color: 'error' },
  { q: 1, label: 'Hard', color: 'error' },
  { q: 2, label: 'Difficult', color: 'accent' },
  { q: 3, label: 'Good', color: 'success' },
  { q: 4, label: 'Easy', color: 'success' },
  { q: 5, label: 'Perfect', color: 'primary' },
];

const FlashcardReview = () => {
  const { dueCards, reviewCard } = useFlashcards();
  const [index, setIndex] = useState(0);
  const [flipped, setFlipped] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  const card = dueCards[index];
  if (!card) return null;

  const handleQuality = async (quality) => {
    setSubmitting(true);
    try {
      await reviewCard(card.id, quality);
      setFlipped(false);
      setIndex(0);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto">
      <div className="text-center text-sm text-text-secondary mb-4">
        Card {index + 1} of {dueCards.length}
      </div>

      <button
        type="button"
        onClick={() => setFlipped(!flipped)}
        className="w-full min-h-[280px] card p-8 flex flex-col items-center justify-center text-center cursor-pointer hover:shadow-warm-md transition-shadow focus:outline-none focus:ring-2 focus:ring-primary"
        aria-label={flipped ? 'Show question' : 'Show answer'}
      >
        <span className="text-xs uppercase tracking-wide text-text-secondary mb-4">
          {flipped ? 'Answer' : 'Question'}
        </span>
        <p className="text-xl font-heading font-semibold text-text-primary">
          {flipped ? card.back : card.front}
        </p>
        {!flipped && (
          <p className="text-sm text-text-secondary mt-6">Tap to reveal answer</p>
        )}
      </button>

      {flipped && (
        <div className="mt-6">
          <p className="text-sm text-text-secondary text-center mb-4">How well did you recall this?</p>
          <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
            {QUALITY_LABELS.map(({ q, label }) => (
              <button
                key={q}
                disabled={submitting}
                onClick={() => handleQuality(q)}
                className="btn btn-outline py-3 text-sm"
              >
                {label}
              </button>
            ))}
          </div>
        </div>
      )}

      {card.tags?.length > 0 && (
        <div className="flex flex-wrap gap-2 mt-4 justify-center">
          {card.tags.map((tag) => (
            <span key={tag} className="text-xs px-2 py-1 bg-surface-100 rounded-full text-text-secondary">
              {tag}
            </span>
          ))}
        </div>
      )}
    </div>
  );
};

export default FlashcardReview;
