import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import Icon from 'components/AppIcon';
import { useFlashcards } from '../../contexts/FlashcardContext';
import LoadingState from '../../components/ui/LoadingState';
import ErrorState from '../../components/ui/ErrorState';
import FlashcardReview from './components/FlashcardReview';
import FlashcardStats from './components/FlashcardStats';
import CreateFlashcardModal from './components/CreateFlashcardModal';

const FlashcardsPage = () => {
  const { dueCards, stats, loading, error, refresh, seedDeck } = useFlashcards();
  const [mode, setMode] = useState('review');
  const [showCreate, setShowCreate] = useState(false);
  const [seeding, setSeeding] = useState(false);

  const handleSeed = async () => {
    setSeeding(true);
    try {
      await seedDeck();
    } finally {
      setSeeding(false);
    }
  };

  if (loading && !stats) return <LoadingState message="Loading flashcards..." />;
  if (error) return <ErrorState message={error} onRetry={refresh} />;

  const hasCards = (stats?.total || 0) > 0;

  return (
    <div className="min-h-screen bg-background">
      <div className="container mx-auto px-4 py-8 max-w-5xl">
        <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4 mb-8">
          <div>
            <h1 className="text-2xl lg:text-3xl font-heading font-bold text-text-primary">
              Spaced Repetition Flashcards
            </h1>
            <p className="text-text-secondary mt-1">
              SM-2 algorithm schedules reviews for long-term retention
            </p>
          </div>
          <div className="flex flex-wrap gap-2">
            {!hasCards && (
              <button onClick={handleSeed} disabled={seeding} className="btn btn-primary px-4 py-2 text-sm">
                <Icon name="Sparkles" size={16} className="mr-2" />
                {seeding ? 'Generating...' : 'Generate from Curriculum'}
              </button>
            )}
            <button onClick={() => setShowCreate(true)} className="btn btn-outline px-4 py-2 text-sm">
              <Icon name="Plus" size={16} className="mr-2" />
              Add Card
            </button>
            <Link to="/course-catalog" className="btn btn-outline px-4 py-2 text-sm">
              Browse Courses
            </Link>
          </div>
        </div>

        <FlashcardStats stats={stats} dueCount={dueCards.length} />

        <div className="flex gap-2 mb-6 border-b border-border">
          {['review', 'browse'].map((tab) => (
            <button
              key={tab}
              onClick={() => setMode(tab)}
              className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
                mode === tab
                  ? 'border-primary text-primary'
                  : 'border-transparent text-text-secondary hover:text-text-primary'
              }`}
            >
              {tab === 'review' ? `Review (${dueCards.length})` : 'All Cards'}
            </button>
          ))}
        </div>

        {mode === 'review' ? (
          dueCards.length > 0 ? (
            <FlashcardReview />
          ) : (
            <div className="card p-12 text-center">
              <Icon name="CheckCircle" size={48} className="mx-auto text-success mb-4" />
              <h2 className="text-xl font-heading font-semibold mb-2">All caught up!</h2>
              <p className="text-text-secondary mb-4">No cards due today. Complete a lesson to add more.</p>
              <Link to="/course-catalog" className="btn btn-primary">
                Continue Learning
              </Link>
            </div>
          )
        ) : (
          <FlashcardBrowse />
        )}

        {showCreate && <CreateFlashcardModal onClose={() => setShowCreate(false)} />}
      </div>
    </div>
  );
};

function FlashcardBrowse() {
  const { cards } = useFlashcards();
  if (!cards.length) {
    return (
      <p className="text-text-secondary text-center py-8">
        No flashcards yet. Generate from your curriculum or add custom cards.
      </p>
    );
  }
  return (
    <div className="grid gap-3">
      {cards.map((card) => (
        <div key={card.id} className="card p-4 flex flex-col sm:flex-row sm:items-center gap-3">
          <div className="flex-1">
            <p className="font-medium text-text-primary">{card.front}</p>
            <p className="text-sm text-text-secondary mt-1">{card.back}</p>
          </div>
          <div className="flex gap-4 text-xs text-text-secondary">
            <span>Interval: {card.interval || 0}d</span>
            <span>Ease: {(card.easeFactor || 2.5).toFixed(1)}</span>
            <span>Due: {card.dueDate}</span>
          </div>
        </div>
      ))}
    </div>
  );
}

export default FlashcardsPage;
