import React from 'react';
import Icon from 'components/AppIcon';

const FlashcardStats = ({ stats, dueCount }) => {
  if (!stats) return null;

  const items = [
    { label: 'Total Cards', value: stats.total, icon: 'Layers' },
    { label: 'Due Today', value: dueCount ?? stats.dueToday, icon: 'Clock' },
    { label: 'Mature', value: stats.mature, icon: 'Award' },
    { label: 'Avg Ease', value: stats.avgEase, icon: 'TrendingUp' },
  ];

  return (
    <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
      {items.map((item) => (
        <div key={item.label} className="card p-4">
          <div className="flex items-center gap-2 mb-2">
            <Icon name={item.icon} size={18} className="text-primary" />
            <span className="text-sm text-text-secondary">{item.label}</span>
          </div>
          <p className="text-2xl font-heading font-bold text-text-primary">{item.value}</p>
        </div>
      ))}
    </div>
  );
};

export default FlashcardStats;
